package main
import "std/io"
import "std/conc"
func middle(n Int) IO[Int] {
  if n == 0 { ioPure(0) } else { do {
    value <- middle(n - 1)
    ioPure(value + 1)
  } }
}
func main() IO[Unit] { do {
  fiber <- conc.fork(middle(5))
  forked <- conc.await(fiber)
  folded <- io.foldLines("/tmp/go4t-DirectIO-examples-w7br4fgr/lines.txt", 0, func(total, _line) => do {
    value <- middle(6)
    ioPure(total + value)
  })
  recovered <- io.tryIO(middle(7))
  println("${forked} ${folded} ${debug(recovered)}")
} }

